/**
 * AXONIZ Security Middleware — strict device auth
 *
 * ONLY localhost is auto-trusted (the machine running `axoniz --web`).
 * EVERY other device — local network, WiFi, internet, Cloudflare tunnel —
 * must enter a 9-digit one-time code generated by:
 *   - CLI: `axoniz auth --temp-device-code`
 *   - Dashboard: /settings/devices (click "Generate code")
 *
 * Flow:
 * 1. Main device: runs `axoniz --web` → opens http://localhost:7860
 *    → cookie set automatically → works forever
 *
 * 2. New device (phone, another laptop, internet):
 *    → opens http://your-server:7860 → no cookie → redirected to /auth/device
 *    → user enters 9-digit code (from terminal or dashboard)
 *    → cookie set → works forever from this device
 *
 * 3. Code expires after 5 minutes. Only one code valid at a time.
 *    New code invalidates the old one.
 *
 * To generate a code: POST /api/axoniz/auth/generate-code (localhost only)
 * To verify a code: POST /api/axoniz/auth/device { code: "123456789" }
 */

import { NextRequest, NextResponse } from "next/server";
import { readFileSync, writeFileSync, existsSync, mkdirSync } from "node:fs";
import path from "node:path";
import os from "node:os";
import crypto from "node:crypto";

let cachedSecret: string | null = null;

function getAxonizHome(): string {
  return path.join(os.homedir(), ".axoniz");
}

function getSecret(): string {
  if (cachedSecret) return cachedSecret;
  const secretPath = path.join(getAxonizHome(), "web-secret");
  try {
    if (existsSync(secretPath)) {
      cachedSecret = readFileSync(secretPath, "utf-8").trim();
      return cachedSecret;
    }
  } catch { /* fall through */ }
  cachedSecret = crypto.randomBytes(32).toString("hex");
  try {
    mkdirSync(getAxonizHome(), { recursive: true });
    writeFileSync(secretPath, cachedSecret, { mode: 0o600 });
  } catch { /* in-memory */ }
  return cachedSecret;
}

function isLocalhost(ip: string): boolean {
  return ip === "127.0.0.1" || ip === "::1" || ip === "::ffff:127.0.0.1" || ip === "unknown";
}

function getClientIP(req: NextRequest): string {
  const xff = req.headers.get("x-forwarded-for");
  if (xff) { const first = xff.split(",")[0]?.trim(); if (first) return first; }
  return req.headers.get("x-real-ip") ?? "127.0.0.1";
}

// Paths that are ALWAYS accessible (no cookie needed)
const PUBLIC_PATHS = [
  "/auth/device",           // the code entry page
  "/api/axoniz/auth/device", // POST: verify code
  "/api/axoniz/health",      // health check (public)
  "/api/axoniz/stream",      // SSE stream (public)
];

function isPublicPath(pathname: string): boolean {
  return PUBLIC_PATHS.some(p => pathname === p || pathname.startsWith(p + "/"));
}

export function middleware(req: NextRequest) {
  const secret = getSecret();
  const clientIP = getClientIP(req);
  const pathname = req.nextUrl.pathname;

  // ── Public paths: always accessible ──────────────────────────────
  if (isPublicPath(pathname)) {
    return NextResponse.next();
  }

  // ── Static assets: always accessible ────────────────────────────
  if (pathname.startsWith("/_next/") ||
      pathname.startsWith("/favicon") ||
      pathname.match(/\.(css|js|woff2?|svg|png|jpg|ico)$/)) {
    return NextResponse.next();
  }

  // ── Check device cookie ─────────────────────────────────────────
  const deviceCookie = req.cookies.get("axoniz_device")?.value;
  if (deviceCookie === secret) {
    // Cookie matches — device is authorized. Check CSRF on writes.
    return checkCSRF(req);
  }

  // ── One-time link (?key=SECRET) for any network ─────────────────
  const urlKey = req.nextUrl.searchParams.get("key");
  if (urlKey && urlKey === secret) {
    // Valid one-time link → set cookie + redirect without ?key= in URL
    const cleanUrl = pathname + req.nextUrl.search.replace(/[?&]key=[^&]*/, "");
    const response = NextResponse.redirect(new URL(cleanUrl || "/", req.url), 302);
    response.cookies.set("axoniz_device", secret, {
      httpOnly: true, sameSite: "strict", path: "/", maxAge: 60 * 60 * 24 * 365,
    });
    return response;
  }

  // ── localhost → auto-trust (the main device) ─────────────────────
  if (isLocalhost(clientIP)) {
    const response = NextResponse.next();
    response.cookies.set("axoniz_device", secret, {
      httpOnly: true, sameSite: "strict", path: "/", maxAge: 60 * 60 * 24 * 365,
    });
    return response;
  }

  // ── Everything else → redirect to device code entry page ─────────
  // Non-localhost, no cookie, no key → must enter 9-digit code
  const isApiRoute = pathname.startsWith("/api/");

  if (isApiRoute) {
    return NextResponse.json(
      { error: "Device not authorized. Enter the 9-digit code at /auth/device" },
      { status: 403 },
    );
  }

  // Page route → redirect to /auth/device
  return NextResponse.redirect(new URL("/auth/device", req.url), 302);
}

function checkCSRF(req: NextRequest): NextResponse {
  const method = req.method.toUpperCase();
  if (!["POST", "PUT", "DELETE", "PATCH"].includes(method)) {
    return NextResponse.next();
  }
  const origin = req.headers.get("origin");
  if (origin) {
    const host = req.headers.get("host") ?? "";
    if (origin !== `http://${host}` && origin !== `https://${host}`) {
      return NextResponse.json(
        { error: "Cross-origin request blocked — CSRF protection." },
        { status: 403 },
      );
    }
  }
  return NextResponse.next();
}

export const config = {
  // Match ALL routes (pages + API) except static assets
  matcher: ["/((?!_next/static|_next/image).*)"],
};
